return (() => { window.__sk = (plane, ents, name) => { const m = window.__mymechanics; const part = m.active(); const id = 'sk' + Math.random().toString(36).slice(2, 8); m.actions.change('op.addSketch', () => { part.features.push({ id, type: 'sketch', name: name || ('S' + part.features.length), plane, entities: [{ id: 'O', type: 'point', x: 0, y: 0, fixed: true, origin: true }, ...ents], constraints: [] }); }); return id; };
window.__rect = (x0, y0, x1, y1, p = 'r') => [{ id: p + 'a', type: 'point', x: x0, y: y0 }, { id: p + 'b', type: 'point', x: x1, y: y0 }, { id: p + 'c', type: 'point', x: x1, y: y1 }, { id: p + 'd', type: 'point', x: x0, y: y1 }, { id: p + '1', type: 'line', p1: p + 'a', p2: p + 'b' }, { id: p + '2', type: 'line', p1: p + 'b', p2: p + 'c' }, { id: p + '3', type: 'line', p1: p + 'c', p2: p + 'd' }, { id: p + '4', type: 'line', p1: p + 'd', p2: p + 'a' }];
window.__ok = () => { const m = window.__mymechanics; const b = m.actions.buildPart(m.active()); return [...b.result.results.values()].filter((r) => r.ok === false).map((r) => r.error).join(',') || 'ok'; };
window.__vol = () => { const m = window.__mymechanics; const b = m.actions.buildPart(m.active()); return b.body ? Math.round(window.__R.measureVolume(b.body)) : 0; };
window.__box = () => { const m = window.__mymechanics; const [lo, hi] = m.actions.buildPart(m.active()).body.boundingBox.bounds; return [0, 1, 2].map((i) => Math.round((hi[i] - lo[i]) * 100) / 100); };
return 'ok'; })()

return (() => {
  const m = window.__mymechanics;
  // Commands that leave the page, open the system's file dialogs, or change what the next ones run in.
  const SKIP = new Set(['exit', 'closeProject', 'exitProject', 'open', 'importStep', 'save', 'saveAs', 'print', 'exportStep', 'exportStl', 'exportImage', 'exportDxf', 'exportSvg', 'designTable', 'importTable', 'recent', 'recentFolders', 'clearRecent', 'newProjectPart', 'startPage', 'userGuide', 'backgroundImage', 'clearBackground', 'language', 'welcome', 'openExample', 'exportMenu', 'shortcuts', 'settings', 'about', 'themeMenu', 'newPart', 'newAssembly', 'newDrawing', 'std3View', 'delete', 'openPart', 'rename']);
  const errors = [];
  window.addEventListener('error', (e) => errors.push(`window: ${e.message}`));
  window.addEventListener('unhandledrejection', (e) => errors.push(`promise: ${e.reason?.message ?? e.reason}`));
  const origError = console.error;
  console.error = (...a) => { errors.push(`console: ${a.map((x) => x?.message ?? String(x)).join(' ')}`.slice(0, 300)); origError(...a); };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const tidy = async (ref) => {
    if (m.state.editing) m.actions.cancelEditing({ quiet: true });
    try { m.popups.closeAll(); } catch { /* none */ }
    if (m.state.showStart) m.actions.showStartPage(false);
    if (ref && (m.project?.active?.id !== ref.id)) m.actions.switchDocument(ref);
    await sleep(30);
  };
  /** Presses every enabled button of `selector` (real DOM clicks), each followed by a clean up. */
  window.__pressAll = async (selector, done, ref) => {
    const failed = [];
    const ids = [...new Set([...document.querySelectorAll(selector)].map((b) => b.dataset.command).filter(Boolean))];
    for (const id of ids) {
      if (SKIP.has(id) || done.has(id)) continue;
      const btn = [...document.querySelectorAll(selector)].find((b) => b.dataset.command === id);
      if (!btn || btn.disabled) continue;
      done.add(id);
      const before = errors.length;
      const was = m.commands[id]?.checked?.();
      try { btn.click(); } catch (e) { errors.push(String(e)); }
      await sleep(140);
      if (errors.length > before) failed.push(`${id}: ${errors.slice(before).join(' | ')}`);
      await tidy(ref);
      // A toggle (panels, rulers, grid …) is put back so the next buttons run in the same state.
      if (was !== undefined && m.commands[id].checked() !== was && m.menus.enabled(id)) { await m.run(id); await tidy(ref); }
    }
    return failed;
  };
  /** Every command of the menus that is enabled here (run as the menus do). */
  window.__runMenus = async (done, ref) => {
    const failed = [];
    const ids = new Set();
    const walk = (items) => { for (const it of items) { if (typeof it === 'string') { if (it !== '-') ids.add(it); } else if (it?.sub) walk(m.menus.SUBMENUS[it.sub].items); } };
    for (const items of Object.values(m.menus.MENUS)) walk(items);
    for (const id of ids) {
      if (SKIP.has(id) || done.has(id) || !m.menus.enabled(id)) continue;
      done.add(id);
      const before = errors.length;
      const was = m.commands[id]?.checked?.();
      const r = m.run(id);
      await Promise.race([r, sleep(400)]).catch((e) => errors.push(String(e)));
      if (errors.length > before) failed.push(`${id}: ${errors.slice(before).join(' | ')}`);
      await tidy(ref);
      if (was !== undefined && m.commands[id].checked() !== was && m.menus.enabled(id)) { await m.run(id); await tidy(ref); }
    }
    return failed;
  };
  /** Every tab: CommandManager tabs (with their buttons), panel tabs and the document tabs. */
  window.__exercise = async () => {
    const ref = { ...m.project.active };
    const done = new Set();
    const failed = [];
    for (const tab of [...document.querySelectorAll('[data-cm-tab]')].map((x) => x.dataset.cmTab)) {
      document.querySelector(`[data-cm-tab="${tab}"]`)?.click();
      await sleep(80);
      if (!document.querySelector(`[data-cm-tab="${tab}"]`)?.classList.contains('active')) failed.push(`cm tab ${tab} did not open`);
      failed.push(...await window.__pressAll('#palette-host [data-command]', done, ref));
    }
    failed.push(...await window.__pressAll('#toolbar [data-command]', done, ref));
    failed.push(...await window.__pressAll('#menubar [data-command]', done, ref));
    // The panels open (an earlier button may have folded one), nothing focused (a real click would blur it).
    for (const [id, key] of [['leftPanel', 'showLeftPanel'], ['rightPanel', 'showRightPanel'], ['bottomPanel', 'showBottomPanel']]) if (!m.state.settings[key]) await m.run(id);
    await sleep(100);
    for (const sel of ['data-left-tab', 'data-right-tab', 'data-bottom-tab']) {
      for (const v of [...document.querySelectorAll(`[${sel}]`)].map((x) => x.getAttribute(sel))) {
        // Re-query: the previous click re-rendered the panel, so earlier nodes are detached.
        const el = document.querySelector(`[${sel}="${v}"]`);
        if (!el || el.disabled) continue;
        document.activeElement?.blur?.(); el.click(); await sleep(120);
        const now = document.querySelector(`[${sel}="${v}"]`);
        if (!now?.classList.contains('active')) failed.push(`${sel}=${v} did not open`);
      }
    }
    failed.push(...await window.__runMenus(done, ref));
    return { failed, count: done.size };
  };
  return 'ok';
})()
